"""This function returns the nth Fibonacci number."""
def fib(n: Any) -> object {
    i = 0;
    j = 1;
    n = n - 1;
    while (n >= 0) {
        (i, j) = (j, (i + j));
        n = n - 1;
    }
    return i;
}

